route.form:
GLOSS {row.name} ON {dataset} AS $${
  "sql": "SELECT <date column> AS date, <measure> AS value FROM <table>",
  "assumptions": [{"dimension": "<scope|behavior|definition>", "key": "<stable-key>", "assumption": "<the judgment call, and the reading you rejected>", "basis": "<what it rests on>", "confidence": 0.7}]
}$$;
-- or, where no number should be served: GLOSS {row.name} ON {dataset} AS $${"stopped": "<what is missing, and why no number is served>"}$$;

DECLARE ASPECT <name>_check WITH $${
  "type": "object", "required": ["outcome"],
  "properties": {"outcome": {"type": "string"}, "tolerance": {"type": "number"}, "breach_rate": {"type": "number"}}
}$$ AS FACT ON DATASET;
DECLARE WITNESS <name>_w ON <name>_check BY (AGENT, HUMAN) DETECTOR rate_tolerance THRESHOLD 0.0;
DECLARE FUNCTION <name>_check_fn FOR {dataset} AS $$
  SELECT '<what was compared>' AS outcome, <the violation share, as DOUBLE> AS breach_rate
  FROM <the second route to the number>
$$ RETURNS <name>_check;
GLOSS <name>_check ON {dataset} AS $${"outcome": "<what must hold>", "tolerance": <the rate you measured>}$$;

GLOSS app ON review AS $${"title": "{dataset} review"}$$;
GLOSS app_frame ON review.series AS $${"sql": "SELECT metric, period, value FROM metric_series(grain => 'month') WHERE dimension = '' AND metric IN ({metric_list}) ORDER BY metric, period"}$$;
GLOSS app_spec ON review.trend AS $${"spec": "{"$schema":"https://vega.github.io/schema/vega-lite/v6.json","data":{"name":"frame"},"mark":"line","encoding":{"x":{"field":"period","type":"temporal"},"y":{"field":"value","type":"quantitative"},"color":{"field":"metric","type":"nominal"}}}"}$$;
GLOSS app_page ON review.index AS $${"html": "{% extends "shell.html" %}
{% import "modules/tiles.html" as tiles %}
{% block main %}
<div class="tiles">
  {{ tiles::chart(frame="frames/series", spec="specs/trend.vl.json", title="By month", chip="metric_series(grain => 'month')") }}
</div>
{% endblock %}
"}$$;

GLOSS app_page ON {row.app}.index AS $${"html": "{% extends "shell.html" %}
{% import "modules/tiles.html" as tiles %}
{% block main %}
<the page over the app's frames and specs — the glossql-apps skill>
{% endblock %}
"}$$;
